using Ganss.Xss;namespace MyDoc.Services;public interface IHtmlSafetyService{string Sanitize(string?html);}public sealed class HtmlSafetyService:IHtmlSafetyService{readonly HtmlSanitizer sanitizer=new();public HtmlSafetyService(){sanitizer.AllowedTags.Clear();sanitizer.AllowedTags.UnionWith(["p","br","strong","b","em","i","u","s","strike","h1","h2","h3","blockquote","pre","code","ul","ol","li","a","span","div"]);sanitizer.AllowedAttributes.Clear();sanitizer.AllowedAttributes.UnionWith(["href","title","target","rel","class","style"]);sanitizer.AllowedCssProperties.Clear();sanitizer.AllowedCssProperties.UnionWith(["color","background-color","text-align","margin-left","font-size"]);sanitizer.AllowedSchemes.Clear();sanitizer.AllowedSchemes.UnionWith(["http","https","mailto"]);}public string Sanitize(string?html)=>string.IsNullOrWhiteSpace(html)?"<p><br></p>":sanitizer.Sanitize(html.Length>500_000?html[..500_000]:html);}
